"""Bundled assets keep the web client installable without a frontend build."""
HTML = '''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>VALORANT Tracker</title><link rel="stylesheet" href="/style.css"><script src="/app.js" defer></script></head>
<body><aside><a class="brand" href="/">V<span>TRACKER</span></a><p class="eyebrow">YOUR GAME, IN FOCUS</p>
<nav aria-label="Tracker views"><button data-command="rank" class="active">01 <span>Rank overview</span></button>
<button data-command="today">02 <span>Today's session</span></button><button data-command="matches">03 <span>Career</span></button>
<button data-command="stats">04 <span>Performance</span></button><button data-command="kd">05 <span>Kill / death</span></button>
<button data-command="hs">06 <span>Headshots</span></button><button data-command="hours">07 <span>Agent hours</span></button>
<button data-command="rr">08 <span>RR history</span></button><button data-command="last">09 <span>Last match</span></button>
<button data-command="profile">10 <span>Player profile</span></button></nav>
<div class="local"><i></i> LOCAL CLIENT <small>Powered by HenrikDev</small></div></aside>
<main><header><span class="eyebrow">VALORANT / PLAYER INTELLIGENCE</span><span class="tag">LIQUID / 01</span></header>
<section class="intro"><p class="eyebrow">MAKE EVERY MATCH COUNT</p><h1 id="view-title">Your next rank<br>starts here.</h1><p id="view-description">Find your form. Track your climb. See the numbers behind your game.</p></section>
<form id="search"><div class="search-row"><label class="player-field">RIOT ID<input id="player" placeholder="Player#TAG" autocomplete="off" required maxlength="120"></label><button class="primary" id="submit" type="submit">Look up player <span>↗</span></button></div>
<div class="options"><label>REGION<select id="region"><option value="">Auto-detect</option><option>ap</option><option>eu</option><option>na</option><option>kr</option><option>br</option><option>latam</option></select></label>
<label>PLATFORM<select id="platform"><option value="pc">PC</option><option value="console">Console</option></select></label>
<label id="count-field">MATCHES<select id="count"><option value="5">5 matches</option><option value="10" selected>10 matches</option></select></label>
<label id="agent-field" hidden>AGENT<input id="agent" placeholder="Clove" maxlength="60"></label>
<label id="pages-field" hidden>HISTORY<select id="pages"><option value="1">Up to 10 games</option><option value="3" selected>Up to 30 games</option><option value="10">Up to 100 games</option></select></label>
<label id="utc-field" class="check" hidden><input type="checkbox" id="utc"> Use UTC</label></div></form>
<p id="status" role="status" aria-live="polite">Ready when you are.</p>
<section id="result" hidden><div class="result-heading"><div><p class="eyebrow">PLAYER REPORT</p><h2 id="result-name"></h2></div><span id="result-view" class="tag"></span></div><div id="cards" class="cards"></div><div id="details"></div><details><summary>Full report</summary><pre id="report"></pre></details></section>
<section id="empty" class="empty"><span class="crosshair">⌖</span><div><h2>A clearer view of your game.</h2><p>Enter your Riot ID to load real match data.<br>Stats are requested only when you click Look up player.</p></div></section>
<footer>For your account and consenting players. Not affiliated with Riot Games.<span>V / TRACKER</span></footer></main></body></html>'''

CSS = '''
:root{color-scheme:dark;--text:#f3f4ff;--muted:#a8adc8;--line:rgba(255,255,255,.12);--glass:rgba(28,32,55,.65);--accent:#c7baff;--mint:#8ce8d5}
*{box-sizing:border-box} [hidden]{display:none!important}
body{margin:0;min-height:100vh;background:#0b0e1b;color:var(--text);font:15px/1.5 "Segoe UI",Arial,sans-serif}
body:before{content:"";position:fixed;inset:0;z-index:-1;pointer-events:none;background:radial-gradient(ellipse at 78% 12%,#49367580,transparent 48%),radial-gradient(ellipse at 18% 65%,#164f6470,transparent 45%),radial-gradient(ellipse at 90% 95%,#542b4e60,transparent 45%)}
button,input,select{font:inherit}button{cursor:pointer}button,a,input,select,summary{ -webkit-tap-highlight-color:transparent}
button:focus-visible,a:focus-visible,summary:focus-visible{outline:2px solid var(--mint);outline-offset:4px}
aside,form,.card,.empty,.table-wrap,details{background:var(--glass);border:1px solid var(--line);box-shadow:inset 0 1px 0 #ffffff12,0 16px 45px #00000018;backdrop-filter:blur(24px);-webkit-backdrop-filter:blur(24px)}
aside{position:fixed;inset:18px auto 18px 18px;width:236px;border-radius:28px;padding:28px 18px;display:flex;flex-direction:column;overflow-y:auto}
.brand{font-size:32px;font-weight:900;letter-spacing:-3px;color:#d4c8ff;text-decoration:none;display:flex;align-items:center;gap:15px;padding:0 12px}.brand span{font-size:15px;letter-spacing:3px;color:var(--text)}
.eyebrow{font-size:10px;font-weight:650;letter-spacing:2px;color:var(--muted)}aside>.eyebrow{font-size:8px;margin:8px 12px 30px}
nav{display:grid;gap:5px}nav button{background:transparent;border:1px solid transparent;border-radius:14px;color:var(--muted);text-align:left;padding:12px;font-size:10px;display:flex;align-items:center;gap:14px;transition:background .22s,transform .22s,color .22s,border-color .22s}nav button span{font-size:13px}nav button:hover{background:#ffffff0b;color:white;transform:translateX(3px)}nav button.active{background:linear-gradient(115deg,#c4b6ff24,#ffffff0a);border-color:#d5caff30;color:#e5ddff;box-shadow:inset 0 1px #ffffff15}nav button:disabled{cursor:wait}
.local{margin-top:auto;padding:28px 12px 0;font-size:9px;letter-spacing:2px}.local i{display:inline-block;width:6px;height:6px;border-radius:50%;background:var(--mint);box-shadow:0 0 12px #8ce8d570;margin-right:8px}.local small{display:block;color:var(--muted);margin-top:8px;letter-spacing:0}
main{margin-left:272px;max-width:1500px;padding:34px clamp(24px,5vw,88px)}header{display:flex;justify-content:space-between;align-items:center;gap:14px}.tag{border:1px solid var(--line);border-radius:30px;padding:7px 12px;color:#c4c5de;font-size:9px;letter-spacing:1.5px;background:#ffffff05}
.intro{margin:56px 0 30px}.intro>.eyebrow{color:#c8bbff}h1{font-size:clamp(40px,5.2vw,72px);line-height:1.06;letter-spacing:-3px;margin:18px 0;font-weight:650;text-wrap:balance;background:linear-gradient(120deg,#fff 15%,#e7ddff 55%,#a8d9e4);background-clip:text;-webkit-background-clip:text;color:transparent}.intro>p:last-child{color:var(--muted);max-width:600px;font-size:14px}
form{border-radius:24px;padding:24px;transition:border-color .25s,box-shadow .25s}form:focus-within{border-color:#c5b7ff50;box-shadow:inset 0 1px #ffffff20,0 20px 50px #00000020}.search-row{display:flex;gap:16px;align-items:end}label{font-size:9px;font-weight:650;letter-spacing:1.5px;color:#bdc0d8;display:flex;flex-direction:column;gap:9px}.player-field{flex:1;min-width:0}
input,select{background:#0c10264d;color:var(--text);border:1px solid var(--line);padding:12px 14px;border-radius:12px;min-width:0;letter-spacing:0;font-size:14px;transition:background .2s,border-color .2s,box-shadow .2s}select option{background:#1b2034}input:focus,select:focus{outline:0;border-color:#c7baff;box-shadow:0 0 0 3px #c7baff18;background:#171b33}input::placeholder{color:#838ba9}.player-field input{font-size:17px;padding:13px 16px}
.primary{position:relative;background:linear-gradient(120deg,#e4dcff,#bab2f6 65%,#a9d3ec);color:#202039;border:1px solid #ffffff65;border-radius:14px;font-weight:700;padding:16px 22px;min-width:190px;box-shadow:inset 0 1px #fff9,0 6px 22px #b6a3ff20;transition:transform .2s,box-shadow .2s,filter .2s}.primary span{margin-left:18px}.primary:hover{transform:translateY(-2px);box-shadow:inset 0 1px #fff9,0 10px 28px #b6a3ff40;filter:brightness(1.07)}.primary:active{transform:translateY(0)}.primary:disabled{opacity:.65;cursor:wait;transform:none}.options{display:flex;gap:16px;margin-top:22px;flex-wrap:wrap}.options label{min-width:120px}.options .check{flex-direction:row;align-items:center;align-self:end;padding:12px 0}.check input{accent-color:#c7baff}
#status{font-size:12px;color:var(--muted);min-height:24px;margin:18px 6px;display:flex;align-items:center;gap:9px}#status.error{color:#ffacbe}body.loading #status:before{content:"";width:12px;height:12px;border:2px solid #c7baff30;border-top-color:var(--accent);border-radius:50%;animation:spin .8s linear infinite}
.result-heading{display:flex;justify-content:space-between;align-items:center;gap:14px;margin:30px 0 20px}.result-heading h2{font-size:26px;margin:4px 0;letter-spacing:-.8px;overflow-wrap:anywhere}.result-heading p{margin:0}.cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.card{position:relative;border-radius:22px;padding:24px;overflow:hidden;transition:transform .25s,border-color .25s}.card:first-child{background:linear-gradient(135deg,#b5a0f52b,#222b454d);border-color:#c7baff38}.card:hover{transform:translateY(-3px);border-color:#ffffff30}.card small{display:block;color:#c0c1d9;font-size:9px;letter-spacing:1.6px}.card strong{display:block;font-size:clamp(27px,3vw,38px);font-weight:650;letter-spacing:-1px;margin:12px 0 0;overflow-wrap:anywhere}.card p{font-size:11px;color:var(--muted);margin:7px 0 0}
.table-wrap{overflow:auto;border-radius:20px;margin-top:22px}table{width:100%;border-collapse:collapse;white-space:nowrap;font-size:13px}th,td{padding:16px 20px;text-align:left;border-bottom:1px solid #ffffff09}th{color:#bdc0d7;font-size:9px;letter-spacing:1.4px;background:#ffffff04}tbody tr{transition:background .2s}tbody tr:hover{background:#ffffff04}tr:last-child td{border:0}.win,.positive{color:var(--mint)}.loss,.negative{color:#ffa9bb}.draw,.neutral{color:#ffd379}.note{font-size:12px;color:var(--muted);margin:15px 4px}details{margin-top:22px;border-radius:18px;padding:18px 22px}summary{cursor:pointer;color:#c3c4dd;font-size:12px}pre{overflow:auto;font:12px/1.8 Consolas,monospace;color:#c1cede}
.empty{padding:32px;display:flex;align-items:center;gap:24px;margin-top:24px;border-radius:24px;background:#ffffff03}.empty h2{font-size:19px;font-weight:550;color:#e0dff0;margin:0 0 8px}.empty p{font-size:13px;color:var(--muted);margin:0;line-height:1.8}.crosshair{flex-shrink:0;width:72px;height:72px;display:grid;place-items:center;font-size:44px;color:#cfc4f7;border:1px solid #ffffff18;border-radius:23px;background:linear-gradient(140deg,#c7baff18,#8ce8d508);box-shadow:inset 0 1px #ffffff18}footer{margin-top:45px;padding:20px 0;color:#9197b2;font-size:10px;display:flex;justify-content:space-between;gap:20px}footer span{letter-spacing:2px;white-space:nowrap}
#result:not([hidden]),.intro,.empty:not([hidden]){animation:arrive .45s cubic-bezier(.2,.75,.25,1) both}.cards .card{animation:arrive .45s both}.cards .card:nth-child(2){animation-delay:.06s}.cards .card:nth-child(3){animation-delay:.12s}@keyframes arrive{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:translateY(0)}}@keyframes spin{to{transform:rotate(360deg)}}
@supports not ((backdrop-filter:blur(1px)) or (-webkit-backdrop-filter:blur(1px))){aside,form,.card,.table-wrap,details{background:#202438}}
@media(min-width:1500px){main{margin-right:auto}}
@media(max-width:1050px){aside{width:210px;inset:14px auto 14px 14px;padding:24px 14px}main{margin-left:238px;padding:28px}.intro{margin-top:42px}.search-row{flex-direction:column;align-items:stretch}.primary{width:100%}.cards{gap:12px}.card{padding:18px}.card strong{font-size:27px}}
@media(max-width:700px){aside{position:static;width:auto;margin:12px;padding:18px;border-radius:22px;overflow:visible}.brand{font-size:26px}aside>.eyebrow,.local{display:none}nav{display:flex;overflow-x:auto;margin-top:16px;gap:6px;padding-bottom:4px;scrollbar-width:thin;scrollbar-color:#ffffff25 transparent}nav button{white-space:nowrap;padding:10px;flex-shrink:0}nav button span{font-size:12px}nav button:hover{transform:none}main{margin:0;padding:16px 20px}header .tag{display:none}header .eyebrow{font-size:8px}h1{font-size:46px;letter-spacing:-2px}.intro{margin-top:30px}form{padding:20px}.options{gap:12px}.options label{flex:1;min-width:110px}.cards{grid-template-columns:1fr}.card{padding:22px}.card strong{font-size:34px}.empty{gap:16px;padding:22px}.crosshair{width:52px;height:60px;font-size:32px;border-radius:18px}.empty h2{font-size:16px}.empty p{font-size:12px}.result-heading{align-items:start}.result-heading .tag{max-width:120px;text-align:center}footer{margin-top:25px;font-size:9px}}
@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation:none!important;transition:none!important;scroll-behavior:auto!important}}
'''

JS = '''"use strict";
const $=id=>document.getElementById(id);
const titles={rank:"Rank overview",today:"Today's session",matches:"Career",stats:"Performance",kd:"Kill / death",hs:"Headshots",hours:"Agent hours",rr:"RR history",last:"Last match",profile:"Player profile"};
let command="rank",busy=false;
function selectCommand(next){if(busy)return;command=next;document.querySelectorAll("nav button").forEach(b=>{b.classList.toggle("active",b.dataset.command===command);b.setAttribute("aria-pressed",b.dataset.command===command)});$("view-title").textContent=titles[command];$("view-description").textContent=command==="hours"?"Time on your agent, measured across available recent matches. This is not lifetime playtime.":"Find your form. Track your climb. See the numbers behind your game.";$("agent-field").hidden=command!=="hours";$("pages-field").hidden=command!=="hours";$("agent").required=command==="hours";$("count-field").hidden=!["matches","stats","kd","hs","rr"].includes(command);$("utc-field").hidden=!["today","rr"].includes(command);$("status").textContent="Ready. Look up your player to load this view.";$("status").className="";$("result").hidden=true;$("empty").hidden=false;}
document.querySelectorAll("nav button").forEach(b=>b.addEventListener("click",()=>selectCommand(b.dataset.command)));
function card(label,value,note="",tone=""){const el=document.createElement("div");el.className="card";for(const [tag,text] of [["small",label],["strong",value],["p",note]]){const node=document.createElement(tag);node.textContent=text;if(tag==="strong"&&tone)node.className=tone;el.append(node)}$("cards").append(el);return el}
function rrTone(value){return value>0?"positive":value<0?"negative":"neutral"}
function table(headers,rows){const wrap=document.createElement("div");wrap.className="table-wrap";const t=document.createElement("table"),head=document.createElement("thead"),body=document.createElement("tbody");const tr=document.createElement("tr");headers.forEach(h=>{const el=document.createElement("th");el.textContent=h;tr.append(el)});head.append(tr);rows.forEach(row=>{const r=document.createElement("tr");row.forEach((value,index)=>{const el=document.createElement("td");el.textContent=value??"--";if(value==="WIN")el.className="win";else if(value==="LOSS")el.className="loss";else if(value==="DRAW")el.className="draw";else if(["CHANGE","RR CHANGE"].includes(headers[index])&&value!=="--"&&Number.isFinite(Number(value)))el.className=rrTone(Number(value));r.append(el)});body.append(r)});t.append(head,body);wrap.append(t);$("details").append(wrap)}
function note(text){const p=document.createElement("p");p.className="note";p.textContent=text;$("details").append(p)}
const signed=n=>n==null?"--":n>=0?"+"+n:String(n),fixed=(n,d=2)=>n==null?"--":n.toFixed(d);
function render(result){const d=result.data;$("cards").replaceChildren();$("details").replaceChildren();$("result-name").textContent=d.account.name+"#"+d.account.tag;$("result-view").textContent=titles[result.command];$("report").textContent=result.text;
if(d.rank){card("CURRENT RANK",d.rank.current?.tier?.name??"Unrated");card("RANK RATING",d.rank.current?.rr??"--","RR in current rank");card("LAST CHANGE",signed(d.rank.current?.last_change),"RR from last match",d.rank.current?.last_change==null?"":rrTone(d.rank.current.last_change))}
else if(d.today){const s=d.today;card("NET RR",signed(s.net_rr),s.missing_rr?"Partial: RR missing for "+s.missing_rr+" games":"Gained "+signed(s.rr_gained)+" / lost "+s.rr_lost,rrTone(s.net_rr));const record=card("SESSION RECORD","",s.draws+" draws · "+s.unknown_results+" unknown").querySelector("strong");for(const [value,tone] of [[s.wins+"W","win"],[" / ",""],[s.losses+"L","loss"]]){const part=document.createElement("span");part.textContent=value;part.className=tone;record.append(part)}card("MATCHES",s.matches,s.date+" · "+s.timezone);table(["MAP","RESULT","RR CHANGE"],s.games.map(g=>[g.map,g.result,g.rr_change==null?"--":signed(g.rr_change)]));(d.notes||[]).forEach(note)}
else if(d.stats){const s=d.stats;card("K / D",fixed(s.kd),s.kills+" kills / "+s.deaths+" deaths");card("HEADSHOT RATE",s.headshot_pct==null?"--":fixed(s.headshot_pct,1)+"%",s.headshots+" head hits");card("WIN RATE",s.win_rate==null?"--":fixed(s.win_rate,1)+"%",s.wins+"W / "+s.losses+"L / "+s.draws+"D");note("Sample: "+s.matches+" recent completed competitive matches.");table(["AGENT","GAMES"],Object.entries(s.agents))}
else if(d.hours){const h=d.hours;card("AGENT HOURS",fixed(h.hours),h.agent);card("AGENT MATCHES",h.agent_matches,"Completed matches");card("GAMES SCANNED",h.scanned_matches,"Recent history across all queues");note(h.scope);if(h.oldest_match)note("Sample: "+h.oldest_match+" to "+h.newest_match);if(h.missing_duration)note("Partial: duration is missing for "+h.missing_duration+" matches.");if(!h.agent_matches)note("No matching agent games found. Check spelling or expand the history sample.")}
else if(d.history){card("RR UPDATES",d.history.length,"Available recent history");table(["DATE (UTC)","MAP","CHANGE","RANK AFTER","RR"],d.history.map(h=>[h.date,h.map?.name,signed(h.last_change),h.tier?.name,h.rr]))}
else if(d.matches){card("MATCHES",d.matches.length,"Available recent games");table(["MAP","AGENT","RESULT","K / D / A"],d.matches.map(m=>{const p=m.players.find(p=>p.puuid===d.account.puuid);const t=m.teams.find(t=>t.team_id===p?.team_id);let result="UNKNOWN";if(m.metadata.is_completed&&t){result=t.rounds?.won!=null&&t.rounds?.won===t.rounds?.lost?"DRAW":t.won===true?"WIN":t.won===false?"LOSS":"UNKNOWN"}return [m.metadata.map?.name,p?.agent?.name,result,p?[p.stats.kills,p.stats.deaths,p.stats.assists].join(" / "):"--"]}));if(!d.matches.length)note("No matches available for this player and queue.")}
else{card("ACCOUNT LEVEL",d.account.account_level??"--");card("REGION",d.account.region?.toUpperCase()??"--");card("PLATFORMS",(d.account.platforms||[]).join(" / "));note("Last updated: "+(d.account.updated_at??"Unknown"))}
$("result").hidden=false;$("empty").hidden=true;}
$("search").addEventListener("submit",async event=>{event.preventDefault();if(busy)return;busy=true;document.body.classList.add("loading");$("search").setAttribute("aria-busy","true");$("submit").disabled=true;$("status").className="";$("status").textContent="Loading player data… This can take a moment.";$("result").hidden=true;$("empty").hidden=true;document.querySelectorAll("nav button").forEach(b=>b.disabled=true);try{const response=await fetch("/api/query",{method:"POST",headers:{"Content-Type":"application/json","X-Tracker-Request":"1"},body:JSON.stringify({command,player:$("player").value.trim(),region:$("region").value,platform:$("platform").value,count:Number($("count").value),pages:Number($("pages").value),agent:$("agent").value.trim(),utc:$("utc").checked})});const data=await response.json();if(!response.ok)throw new Error(data.error||"Lookup failed.");render(data);$("status").textContent="Updated just now · "+titles[command];}catch(error){$("empty").hidden=false;$("status").className="error";$("status").textContent=error.message||"Could not connect. Check the local server."}finally{busy=false;document.body.classList.remove("loading");$("search").setAttribute("aria-busy","false");$("submit").disabled=false;document.querySelectorAll("nav button").forEach(b=>b.disabled=false)}});

$("count-field").hidden=true;document.querySelector('nav button[data-command="rank"]').setAttribute("aria-pressed","true");
'''
